import{_ as s,o as i,c as a,am as t}from"./chunks/framework.yj4qiWdr.js";const u=JSON.parse('{"title":"OSCP · Tunnels et pivot réseau","description":"Ligolo-ng pas à pas, double pivot, listeners, Chisel et SSH.","frontmatter":{"title":"OSCP · Tunnels et pivot réseau","description":"Ligolo-ng pas à pas, double pivot, listeners, Chisel et SSH."},"headers":[],"relativePath":"oscp/tunneling.md","filePath":"oscp/tunneling.md"}'),n={name:"oscp/tunneling.md"};function l(r,e,o,p,h,d){return i(),a("div",null,e[0]||(e[0]=[t(`<h1 id="tunnels-et-pivot-reseau" tabindex="-1">Tunnels et pivot réseau <a class="header-anchor" href="#tunnels-et-pivot-reseau" aria-label="Permalink to &quot;Tunnels et pivot réseau&quot;">​</a></h1><p><strong>Objectif :</strong> atteindre un réseau interne autorisé depuis Kali en passant par une machine de pivot. Le <strong>proxy Ligolo-ng</strong> tourne sur Kali ; l&#39;<strong>agent</strong> tourne sur la machine qui peut voir le réseau interne. Le trajet se fait par un tunnel chiffré.</p><p><strong>Adresses fictives à remplacer :</strong> Kali <code>10.10.14.10</code> · premier pivot Windows <code>10.10.10.30</code> (IP interne <code>172.16.20.1</code>) · réseau interne <code>172.16.20.0/24</code> · deuxième pivot <code>172.16.20.30</code> · second réseau <code>172.16.30.0/24</code>.</p><p>Chaque bloc précise <strong>où exécuter la commande</strong>. Les commandes <code>session</code>, <code>ifconfig</code>, <code>tunnel_start</code> et <code>listener_add</code> se saisissent dans <strong>la console Ligolo</strong>, jamais dans Bash ou PowerShell.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><p>Télécharger les binaires depuis les <a href="https://github.com/nicocha30/ligolo-ng/releases" target="_blank" rel="noreferrer">versions officielles de Ligolo-ng</a> : <strong>proxy</strong> pour Kali, <strong>agent</strong> pour Windows/Linux et pour l&#39;architecture concernée. Dans cette fiche, les binaires sont renommés <code>proxy</code>, <code>agent</code> ou <code>agent.exe</code> et placés dans le répertoire courant. Prévoir les droits nécessaires à la création d&#39;une interface TUN sur Kali ; l&#39;agent ne nécessite généralement pas de privilèges administrateur.</p><p><strong>Compatibilité :</strong> choisir des versions compatibles du proxy et de l&#39;agent et vérifier leur architecture (Linux/Windows, amd64/arm64). Vérifier les options disponibles localement avec <code>./proxy -h</code> et <code>./agent -h</code> (ou <code>agent.exe -h</code> sur Windows).</p><h2 id="ligolo-ng-premier-tunnel" tabindex="-1">Ligolo-ng : premier tunnel <a class="header-anchor" href="#ligolo-ng-premier-tunnel" aria-label="Permalink to &quot;Ligolo-ng : premier tunnel&quot;">​</a></h2><p><strong>Ordre à suivre :</strong> préparer la TUN → démarrer le proxy Kali → relever l&#39;empreinte TLS → connecter l&#39;agent pivot → sélectionner sa session → démarrer le tunnel → ajouter la route sur Kali → tester un port autorisé.</p><h3 id="preparer-l-interface-tun-sur-kali" tabindex="-1">Préparer l&#39;interface TUN sur Kali <a class="header-anchor" href="#preparer-l-interface-tun-sur-kali" aria-label="Permalink to &quot;Préparer l&#39;interface TUN sur Kali&quot;">​</a></h3><p>L&#39;interface TUN transporte les paquets vers Ligolo. Vérifier <code>ip -br link show ligolo</code> avant toute création pour éviter <code>File exists</code>. Cette méthode manuelle fonctionne avec les versions classiques.</p><p class="oscp-command-note">Sur Kali: terminal habituel, avant de lancer le proxy.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tuntap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -br</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span></span></code></pre></div><h3 id="demarrer-le-proxy-sur-kali" tabindex="-1">Démarrer le proxy sur Kali <a class="header-anchor" href="#demarrer-le-proxy-sur-kali" aria-label="Permalink to &quot;Démarrer le proxy sur Kali&quot;">​</a></h3><p>Le binaire <code>proxy</code> vient des versions officielles. Le proxy Ligolo écoute par défaut sur TCP 11601 ; autoriser ce port entre l&#39;agent et Kali.</p><p class="oscp-command-note">Sur Kali: autre terminal, à laisser ouvert.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./proxy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -selfcert</span></span></code></pre></div><h3 id="lire-l-empreinte-du-certificat" tabindex="-1">Lire l&#39;empreinte du certificat <a class="header-anchor" href="#lire-l-empreinte-du-certificat" aria-label="Permalink to &quot;Lire l&#39;empreinte du certificat&quot;">​</a></h3><p>Relever l&#39;empreinte TLS SHA-256 réellement affichée par le proxy : l&#39;agent la comparera au certificat présenté lors de la connexion.</p><p class="oscp-command-note">Dans la console interactive du proxy Ligolo sur Kali.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>certificate_fingerprint</span></span></code></pre></div><h3 id="connecter-un-agent-windows" tabindex="-1">Connecter un agent Windows <a class="header-anchor" href="#connecter-un-agent-windows" aria-label="Permalink to &quot;Connecter un agent Windows&quot;">​</a></h3><p>Sur Windows pivot, transférer <code>agent.exe</code> compatible et remplacer <code>EMPREINTE_SHA256</code> par l&#39;empreinte relevée sur Kali ; le port TCP 11601 doit être joignable.</p><p class="oscp-command-note">Sur le Windows pivot: PowerShell.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">agent.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">connect </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11601</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fingerprint EMPREINTE_SHA256</span></span></code></pre></div><h3 id="connecter-un-agent-linux" tabindex="-1">Connecter un agent Linux <a class="header-anchor" href="#connecter-un-agent-linux" aria-label="Permalink to &quot;Connecter un agent Linux&quot;">​</a></h3><p>Sur un pivot Linux plutôt que Windows, exécuter l&#39;agent adapté à l&#39;architecture ; les commandes Bash ne s&#39;appliquent pas à Windows.</p><p class="oscp-command-note">Sur un pivot Linux: terminal Bash.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.10.14.10:11601</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -accept-fingerprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EMPREINTE_SHA256</span></span></code></pre></div><h3 id="choisir-l-agent-et-reperer-son-reseau" tabindex="-1">Choisir l&#39;agent et repérer son réseau <a class="header-anchor" href="#choisir-l-agent-et-reperer-son-reseau" aria-label="Permalink to &quot;Choisir l&#39;agent et repérer son réseau&quot;">​</a></h3><p>Dans le proxy Ligolo, <code>session</code> sert à sélectionner l&#39;agent connecté ; <code>ifconfig</code> affiche ensuite les interfaces de <strong>cet agent</strong>, pas celles de Kali.</p><p class="oscp-command-note">Dans la console Ligolo sur Kali.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session</span></span>
<span class="line"><span>ifconfig</span></span></code></pre></div><h3 id="demarrer-le-tunnel-sur-l-interface" tabindex="-1">Démarrer le tunnel sur l&#39;interface <a class="header-anchor" href="#demarrer-le-tunnel-sur-l-interface" aria-label="Permalink to &quot;Démarrer le tunnel sur l&#39;interface&quot;">​</a></h3><p><code>ligolo</code> désigne l&#39;interface TUN <strong>sur Kali</strong> ; sélectionner la bonne session agent avant <code>tunnel_start</code>.</p><p class="oscp-command-note">Dans la console Ligolo, **après avoir sélectionné la session**.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tunnel_start --tun ligolo</span></span>
<span class="line"><span>tunnel_list</span></span></code></pre></div><h3 id="ajouter-la-route-du-reseau-interne" tabindex="-1">Ajouter la route du réseau interne <a class="header-anchor" href="#ajouter-la-route-du-reseau-interne" aria-label="Permalink to &quot;Ajouter la route du réseau interne&quot;">​</a></h3><p>Adapter <code>172.16.20.0/24</code> au réseau réellement accessible depuis le pivot. Cette route s&#39;ajoute <strong>sur Kali uniquement</strong>, pas sur Windows.</p><p class="oscp-command-note">Sur Kali: terminal Linux différent de la console proxy.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.16.20.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.16.20.10</span></span></code></pre></div><h3 id="tester-un-service-du-reseau-interne" tabindex="-1">Tester un service du réseau interne <a class="header-anchor" href="#tester-un-service-du-reseau-interne" aria-label="Permalink to &quot;Tester un service du réseau interne&quot;">​</a></h3><p>Tester un port autorisé du réseau interne avant un scan étendu. Le routage via TUN Ligolo ne nécessite pas ProxyChains. <code>--unprivileged</code> réduit le risque de faux positifs liés aux sondes brutes de Nmap.</p><p class="oscp-command-note">Sur Kali : exécuter la commande dans un terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --unprivileged</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80,445,3389</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.16.20.10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://172.16.20.10/</span></span></code></pre></div><p><strong>À savoir :</strong> l&#39;agent Ligolo peut fonctionner sans droits administrateur, mais Kali doit pouvoir créer l&#39;interface TUN. Pour Nmap, commencer par <code>-sT -Pn</code>, puis adapter au contexte ; Ligolo traduit certaines sondes TCP en appels <code>connect()</code> côté pivot.</p><h2 id="autre-facon-de-creer-l-interface-ligolo-recent" tabindex="-1">Autre façon de créer l&#39;interface (Ligolo récent) <a class="header-anchor" href="#autre-facon-de-creer-l-interface-ligolo-recent" aria-label="Permalink to &quot;Autre façon de créer l&#39;interface (Ligolo récent)&quot;">​</a></h2><p>Avec les versions récentes de Ligolo-ng, la console du proxy peut créer l&#39;interface et ajouter la route. <strong>Choisir cette méthode OU la préparation manuelle précédente, pas les deux</strong>. La création requiert les permissions réseau suffisantes sur Kali.</p><h3 id="creer-l-interface-dans-la-console-ligolo" tabindex="-1">Créer l&#39;interface dans la console Ligolo <a class="header-anchor" href="#creer-l-interface-dans-la-console-ligolo" aria-label="Permalink to &quot;Créer l&#39;interface dans la console Ligolo&quot;">​</a></h3><p>La console Ligolo crée une interface TUN <strong>sur Kali</strong>, sous réserve des droits réseau du processus proxy.</p><p class="oscp-command-note">Dans la console Ligolo sur Kali: alternative aux commandes \`ip tuntap\`.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interface_create --name ligolo</span></span></code></pre></div><h3 id="ajouter-la-route-depuis-la-console" tabindex="-1">Ajouter la route depuis la console <a class="header-anchor" href="#ajouter-la-route-depuis-la-console" aria-label="Permalink to &quot;Ajouter la route depuis la console&quot;">​</a></h3><p>Cette commande ajoute sur Kali une route vers le sous-réseau accessible depuis le pivot ; ne pas la cumuler avec une route manuelle identique.</p><p class="oscp-command-note">Dans la console Ligolo sur Kali.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interface_add_route --name ligolo --route 172.16.20.0/24</span></span></code></pre></div><p>Ensuite, sélectionner l&#39;agent avec <code>session</code>, démarrer avec <code>tunnel_start --tun ligolo</code> et tester le routage. Dans les versions récentes, les interfaces et routes peuvent être conservées dans la configuration du proxy.</p><h2 id="atteindre-le-localhost-du-pivot" tabindex="-1">Atteindre le localhost du pivot <a class="header-anchor" href="#atteindre-le-localhost-du-pivot" aria-label="Permalink to &quot;Atteindre le localhost du pivot&quot;">​</a></h2><p><strong>Problème :</strong> un service lié uniquement à <code>127.0.0.1:8000</code> sur le pivot n&#39;écoute pas sur son IP réseau. Ligolo réserve <code>240.0.0.1</code> pour atteindre <strong>le <code>127.0.0.1</code> de l&#39;agent sélectionné</strong> à travers son tunnel.</p><h3 id="ajouter-la-route-speciale-vers-le-localhost-distant" tabindex="-1">Ajouter la route spéciale vers le localhost distant <a class="header-anchor" href="#ajouter-la-route-speciale-vers-le-localhost-distant" aria-label="Permalink to &quot;Ajouter la route spéciale vers le localhost distant&quot;">​</a></h3><p>Ajouter la route <code>240.0.0.1/32</code> sur Kali via la TUN associée à l&#39;agent concerné, après le démarrage du tunnel.</p><p class="oscp-command-note">Sur Kali : exécuter la commande dans un terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 240.0.0.1/32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://240.0.0.1:8000/</span></span></code></pre></div><p><code>curl</code> ne réussira que si un serveur HTTP écoute effectivement sur <code>127.0.0.1:8000</code> du pivot. Éviter de réutiliser cette même adresse avec plusieurs interfaces simultanées sans contrôler la route.</p><h2 id="ligolo-ng-double-pivot" tabindex="-1">Ligolo-ng : double pivot <a class="header-anchor" href="#ligolo-ng-double-pivot" aria-label="Permalink to &quot;Ligolo-ng : double pivot&quot;">​</a></h2><p><strong>Situation :</strong> le pivot B ne peut pas joindre Kali directement, mais peut atteindre l&#39;IP interne du pivot A et son listener TCP. Le premier pivot doit relayer le port Ligolo du deuxième agent vers le proxy sur Kali.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kali (proxy :11601) ⇐ tunnel TLS ⇒ Pivot A (agent Ligolo)</span></span>
<span class="line"><span>                                       ↑ connexion de Pivot B vers A:11602</span></span>
<span class="line"><span>                                       │ listener A → Kali:11601</span></span>
<span class="line"><span>                                 Pivot B (deuxième agent) → réseau 172.16.30.0/24</span></span></code></pre></div><h3 id="creer-un-listener-sur-le-premier-pivot" tabindex="-1">Créer un listener sur le premier pivot <a class="header-anchor" href="#creer-un-listener-sur-le-premier-pivot" aria-label="Permalink to &quot;Créer un listener sur le premier pivot&quot;">​</a></h3><p>Le listener ouvre TCP <code>11602</code> <strong>sur le pivot A</strong> et relaie vers TCP <code>11601</code> <strong>sur Kali</strong> ; vérifier les pare-feu des deux côtés. Ne pas le confondre avec un port ouvert sur Kali.</p><p class="oscp-command-note">Dans la console Ligolo, **session du pivot A** sélectionnée.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listener_add --addr 0.0.0.0:11602 --to 127.0.0.1:11601 --tcp</span></span>
<span class="line"><span>listener_list</span></span></code></pre></div><h3 id="faire-connecter-le-second-agent" tabindex="-1">Faire connecter le second agent <a class="header-anchor" href="#faire-connecter-le-second-agent" aria-label="Permalink to &quot;Faire connecter le second agent&quot;">​</a></h3><p>Sur le pivot B, l&#39;agent contacte <code>172.16.20.1:11602</code> (pivot A) ; ne pas utiliser l&#39;IP de Kali si elle n&#39;est pas routable.</p><p class="oscp-command-note">Sur le pivot B: PowerShell si Windows.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">agent.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">connect </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">172.16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11602</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fingerprint EMPREINTE_SHA256</span></span></code></pre></div><p><strong>Repère :</strong> <code>172.16.20.1</code> est l&#39;interface interne du pivot A et <code>172.16.20.30</code> celle du pivot B. Ces adresses sont fictives. Remplacer ces IP par les vraies interfaces trouvées avec <code>ifconfig</code>.</p><h3 id="creer-la-seconde-interface-tun" tabindex="-1">Créer la seconde interface TUN <a class="header-anchor" href="#creer-la-seconde-interface-tun" aria-label="Permalink to &quot;Créer la seconde interface TUN&quot;">​</a></h3><p>Créer <code>ligolo2</code> sur Kali pour le second tunnel : ne pas faire passer simultanément les deux agents sur la même interface TUN.</p><p class="oscp-command-note">Sur Kali: terminal Linux habituel.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tuntap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><h3 id="selectionner-le-deuxieme-agent" tabindex="-1">Sélectionner le deuxième agent <a class="header-anchor" href="#selectionner-le-deuxieme-agent" aria-label="Permalink to &quot;Sélectionner le deuxième agent&quot;">​</a></h3><p>Dans la console Ligolo, sélectionner la <strong>session du pivot B</strong> avant <code>ifconfig</code> et <code>tunnel_start --tun ligolo2</code>.</p><p class="oscp-command-note">Dans la console Ligolo sur Kali.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session</span></span>
<span class="line"><span>ifconfig</span></span>
<span class="line"><span>tunnel_start --tun ligolo2</span></span></code></pre></div><h3 id="router-le-deuxieme-reseau" tabindex="-1">Router le deuxième réseau <a class="header-anchor" href="#router-le-deuxieme-reseau" aria-label="Permalink to &quot;Router le deuxième réseau&quot;">​</a></h3><p>Sur Kali, router <code>172.16.30.0/24</code> via <code>ligolo2</code> et vérifier la route avant de tester un port du second réseau.</p><p class="oscp-command-note">Sur Kali : exécuter la commande dans un terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.16.30.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.16.30.10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --unprivileged</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 445</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.16.30.10</span></span></code></pre></div><h2 id="listener-ligolo-rendre-un-service-kali-accessible-au-pivot" tabindex="-1">Listener Ligolo : rendre un service Kali accessible au pivot <a class="header-anchor" href="#listener-ligolo-rendre-un-service-kali-accessible-au-pivot" aria-label="Permalink to &quot;Listener Ligolo : rendre un service Kali accessible au pivot&quot;">​</a></h2><p>Un <em>listener</em> ouvre un port TCP sur l&#39;agent sélectionné et redirige les connexions vers un service qui écoute sur le proxy Kali. Pratique pour récupérer un fichier depuis Kali lorsque la cible ne peut pas contacter directement <code>10.10.14.10</code>.</p><h3 id="heberger-le-fichier-sur-kali" tabindex="-1">Héberger le fichier sur Kali <a class="header-anchor" href="#heberger-le-fichier-sur-kali" aria-label="Permalink to &quot;Héberger le fichier sur Kali&quot;">​</a></h3><p>Sur Kali, servir le dossier local uniquement sur <code>127.0.0.1:8000</code> ; le listener Ligolo exposera ce service sur le pivot.</p><p class="oscp-command-note">Sur Kali: terminal Linux séparé.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./partage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./partage</span></span></code></pre></div><h3 id="dans-ligolo-exposer-le-service-http-de-kali-sur-le-pivot-a" tabindex="-1">Dans Ligolo, exposer le service HTTP de Kali sur le pivot A <a class="header-anchor" href="#dans-ligolo-exposer-le-service-http-de-kali-sur-le-pivot-a" aria-label="Permalink to &quot;Dans Ligolo, exposer le service HTTP de Kali sur le pivot A&quot;">​</a></h3><p>Le port <code>8080</code> écoute sur le <strong>pivot A</strong> (<code>172.16.20.1</code>) et redirige vers le serveur HTTP de Kali (<code>127.0.0.1:8000</code>).</p><p class="oscp-command-note">Dans la console Ligolo: session du pivot A.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listener_add --addr 0.0.0.0:8080 --to 127.0.0.1:8000 --tcp</span></span>
<span class="line"><span>listener_list</span></span></code></pre></div><h3 id="telecharger-depuis-une-machine-interne" tabindex="-1">Télécharger depuis une machine interne <a class="header-anchor" href="#telecharger-depuis-une-machine-interne" aria-label="Permalink to &quot;Télécharger depuis une machine interne&quot;">​</a></h3><p>La machine Windows interne contacte <strong>le pivot A à <code>172.16.20.1:8080</code></strong>, pas le pivot B (<code>172.16.20.30</code>). Le fichier doit exister dans <code>./partage/</code> sur Kali.</p><p class="oscp-command-note">Sur Windows interne pouvant joindre l&#39;IP réseau du pivot A.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-WebRequest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseBasicParsing </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Uri </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://172.16.20.1:8080/outil.txt&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutFile </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;C:\\Users\\Public\\outil.txt&#39;</span></span></code></pre></div><p>Pour <strong>envoyer un fichier vers Kali</strong>, <code>python3 -m http.server</code> ne suffit pas (pas d&#39;upload) : utiliser <strong>SMB ou WebDAV</strong> comme expliqué dans la <a href="./transferts">fiche Transferts de fichiers</a>. Un listener Ligolo peut acheminer ces protocoles si le port et le service de réception sont configurés.</p><h2 id="chisel-autre-solution-de-pivot" tabindex="-1">Chisel : autre solution de pivot <a class="header-anchor" href="#chisel-autre-solution-de-pivot" aria-label="Permalink to &quot;Chisel : autre solution de pivot&quot;">​</a></h2><p><strong>Chisel</strong> transporte des redirections TCP et un proxy SOCKS via une connexion client/serveur HTTP encapsulée dans un tunnel chiffré lorsqu&#39;il est configuré en conséquence. Contrairement au tunnel TUN de Ligolo, il peut nécessiter ProxyChains pour les outils qui ne prennent pas en charge SOCKS.</p><h3 id="demarrer-chisel-en-mode-reverse" tabindex="-1">Démarrer Chisel en mode reverse <a class="header-anchor" href="#demarrer-chisel-en-mode-reverse" aria-label="Permalink to &quot;Démarrer Chisel en mode reverse&quot;">​</a></h3><p>Le serveur Chisel de Kali écoute sur TCP <code>8001</code> et autorise les redirections inverses demandées par le client distant ; protéger son accès.</p><p class="oscp-command-note">Sur Kali: serveur Chisel.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chisel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reverse</span></span></code></pre></div><h3 id="rediriger-un-port-interne-vers-kali" tabindex="-1">Rediriger un port interne vers Kali <a class="header-anchor" href="#rediriger-un-port-interne-vers-kali" aria-label="Permalink to &quot;Rediriger un port interne vers Kali&quot;">​</a></h3><p>Le client Chisel sur Windows demande une écoute sur Kali en <code>8080</code> vers son propre <code>127.0.0.1:80</code> ; un serveur doit réellement écouter sur ce port.</p><p class="oscp-command-note">Sur le pivot Windows: client Chisel.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">chisel.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> R:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span></span></code></pre></div><h3 id="tester-le-port-redirige" tabindex="-1">Tester le port redirigé <a class="header-anchor" href="#tester-le-port-redirige" aria-label="Permalink to &quot;Tester le port redirigé&quot;">​</a></h3><p>La connexion aboutit sur le serveur HTTP du pivot, s&#39;il existe.</p><p class="oscp-command-note">Sur Kali: terminal Linux distinct.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/</span></span></code></pre></div><h3 id="creer-un-proxy-socks-inverse" tabindex="-1">Créer un proxy SOCKS inversé <a class="header-anchor" href="#creer-un-proxy-socks-inverse" aria-label="Permalink to &quot;Créer un proxy SOCKS inversé&quot;">​</a></h3><p>Avec <code>R:1080:socks</code>, le port SOCKS <code>1080</code> est exposé côté serveur Chisel sur Kali ; garder la connexion client active.</p><p class="oscp-command-note">Sur le pivot Windows: client Chisel.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">chisel.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14.10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> R:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1080</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:socks</span></span></code></pre></div><h3 id="tester-un-site-interne-via-socks" tabindex="-1">Tester un site interne via SOCKS <a class="header-anchor" href="#tester-un-site-interne-via-socks" aria-label="Permalink to &quot;Tester un site interne via SOCKS&quot;">​</a></h3><p>Avec <code>curl --socks5-hostname</code>, la résolution des noms DNS est déléguée au proxy SOCKS ; l&#39;adresse IP d&#39;exemple n&#39;exige pas de résolution.</p><p class="oscp-command-note">Sur Kali : exécuter la commande dans un terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --socks5-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:1080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://172.16.20.10/</span></span></code></pre></div><p><strong>ProxyChains :</strong> si l&#39;outil n&#39;accepte pas SOCKS directement, ajouter <code>socks5 127.0.0.1 1080</code> à la section <code>[ProxyList]</code> de <code>/etc/proxychains4.conf</code>, puis utiliser <code>proxychains4</code> devant la commande. Vérifier que le serveur SOCKS Chisel est actif ; avec Nmap, utiliser <code>-sT -Pn</code> et éviter les scans SYN/UDP à travers ce proxy.</p><h2 id="ssh-alternative-simple-avec-un-compte-valide" tabindex="-1">SSH : alternative simple avec un compte valide <a class="header-anchor" href="#ssh-alternative-simple-avec-un-compte-valide" aria-label="Permalink to &quot;SSH : alternative simple avec un compte valide&quot;">​</a></h2><p><strong>Quand utiliser SSH ?</strong> Si le pivot dispose d&#39;un serveur SSH accessible et d&#39;un compte autorisé, privilégier les redirections SSH pour les services nécessaires. Pour les transferts de fichiers, utiliser <a href="./transferts">SCP</a>.</p><h3 id="redirection-ssh-locale" tabindex="-1">Redirection SSH locale <a class="header-anchor" href="#redirection-ssh-locale" aria-label="Permalink to &quot;Redirection SSH locale&quot;">​</a></h3><p>Sur Kali, <code>-L</code> ouvre <code>127.0.0.1:8080</code> ; le serveur SSH du pivot se connecte ensuite à <code>172.16.20.10:80</code>.</p><p class="oscp-command-note">Sur Kali: le serveur SSH a accès au service interne.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8080:172.16.20.10:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> etudiant@10.10.10.30</span></span></code></pre></div><h3 id="proxy-socks-par-ssh" tabindex="-1">Proxy SOCKS par SSH <a class="header-anchor" href="#proxy-socks-par-ssh" aria-label="Permalink to &quot;Proxy SOCKS par SSH&quot;">​</a></h3><p>Sur Kali, <code>ssh -D</code> crée un proxy SOCKS sur <code>127.0.0.1:9050</code> ; conserver la session SSH ouverte pendant son utilisation.</p><p class="oscp-command-note">Sur Kali: accès SSH à un pivot.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:9050</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> etudiant@10.10.10.30</span></span></code></pre></div><h3 id="routage-reseau-avec-sshuttle" tabindex="-1">Routage réseau avec sshuttle <a class="header-anchor" href="#routage-reseau-avec-sshuttle" aria-label="Permalink to &quot;Routage réseau avec sshuttle&quot;">​</a></h3><p><code>sshuttle</code> achemine les connexions TCP du sous-réseau via SSH ; il ne remplace pas un VPN complet pour tous les protocoles.</p><p class="oscp-command-note">Sur Kali: sshuttle et SSH accessibles.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sshuttle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> etudiant@10.10.10.30</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.16.20.0/24</span></span></code></pre></div><h2 id="tunnel-dns-avec-dnscat2" tabindex="-1">Tunnel DNS avec dnscat2 <a class="header-anchor" href="#tunnel-dns-avec-dnscat2" aria-label="Permalink to &quot;Tunnel DNS avec dnscat2&quot;">​</a></h2><p>Le tunnel DNS dnscat2 est un exemple avancé réservé à un laboratoire où les échanges DNS sont explicitement autorisés. <strong>Ce n&#39;est pas une étape nécessaire pour Ligolo-ng</strong> : elle est conservée séparément pour éviter de mélanger les outils.</p><h3 id="demarrer-le-serveur-dnscat2" tabindex="-1">Démarrer le serveur dnscat2 <a class="header-anchor" href="#demarrer-le-serveur-dnscat2" aria-label="Permalink to &quot;Démarrer le serveur dnscat2&quot;">​</a></h3><p>Utiliser un domaine DNS réellement contrôlé par le laboratoire, avec les enregistrements nécessaires pour joindre le serveur, et un secret partagé.</p><p class="oscp-command-note">Sur la machine Linux qui héberge le serveur DNS contrôlé.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dnscat2-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laboratoire.example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;SecretDeTest&#39;</span></span></code></pre></div><h3 id="connecter-un-client-dnscat2" tabindex="-1">Connecter un client dnscat2 <a class="header-anchor" href="#connecter-un-client-dnscat2" aria-label="Permalink to &quot;Connecter un client dnscat2&quot;">​</a></h3><p>Le client doit utiliser le même domaine et le même secret que le serveur ; vérifier la délégation et l&#39;accès DNS avant le test.</p><p class="oscp-command-note">Sur le client Linux de laboratoire.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dnscat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --secret=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SecretDeTest&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laboratoire.example</span></span></code></pre></div><p>Les noms de binaires et les options dnscat2 dépendent de la version compilée ou installée. Exécuter <code>dnscat2-server --help</code> et <code>./dnscat --help</code> pour la version locale.</p><h2 id="depannage-ligolo-ng" tabindex="-1">Dépannage Ligolo-ng <a class="header-anchor" href="#depannage-ligolo-ng" aria-label="Permalink to &quot;Dépannage Ligolo-ng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptôme</th><th>Cause à vérifier</th></tr></thead><tbody><tr><td>L&#39;agent n&#39;apparaît pas</td><td>Proxy démarré, IP Kali correcte, TCP 11601 joignable et empreinte TLS valide ?</td></tr><tr><td>Empreinte TLS refusée</td><td>Relever <code>certificate_fingerprint</code> sur le proxy actif et recopier l&#39;empreinte sans erreur dans l&#39;agent</td></tr><tr><td><code>no such device</code> / TUN absent</td><td>Vérifier <code>ip -br link show ligolo</code> sur Kali ; créer ou sélectionner l&#39;interface TUN appropriée</td></tr><tr><td><code>RTNETLINK answers: File exists</code></td><td>Une interface ou une route existe déjà ; vérifier <code>ip -br link</code> et <code>ip route</code> avant toute modification</td></tr><tr><td>Tunnel lancé mais réseau inaccessible</td><td>Contrôler la session sélectionnée, le sous-réseau de l&#39;agent, la route Kali et les pare-feu</td></tr><tr><td>Second agent non connecté</td><td>Vérifier le listener TCP sur pivot A, son IP interne et l&#39;accès depuis pivot B à <code>11602</code></td></tr><tr><td>Service sur <code>127.0.0.1</code> de l&#39;agent inaccessible</td><td>Router <code>240.0.0.1/32</code> vers la bonne TUN et vérifier que le service écoute sur l&#39;agent</td></tr><tr><td>Port redirigé muet</td><td>Vérifier le service sur Kali, le port <code>--to</code>, le port <code>--addr</code> sur l&#39;agent et le pare-feu</td></tr></tbody></table><h2 id="arreter-et-nettoyer" tabindex="-1">Arrêter et nettoyer <a class="header-anchor" href="#arreter-et-nettoyer" aria-label="Permalink to &quot;Arrêter et nettoyer&quot;">​</a></h2><h3 id="fermer-le-tunnel" tabindex="-1">Fermer le tunnel <a class="header-anchor" href="#fermer-le-tunnel" aria-label="Permalink to &quot;Fermer le tunnel&quot;">​</a></h3><p>Dans Ligolo, sélectionner l&#39;agent concerné avant <code>tunnel_stop</code>. Les listeners restent indépendants : consulter <code>listener_list</code>, puis arrêter chacun par son identifiant.</p><p class="oscp-command-note">Dans la console Ligolo: sélectionner la bonne session.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session</span></span>
<span class="line"><span>tunnel_stop</span></span>
<span class="line"><span>listener_list</span></span></code></pre></div><h3 id="supprimer-la-route-apres-l-examen" tabindex="-1">Supprimer la route après l&#39;examen <a class="header-anchor" href="#supprimer-la-route-apres-l-examen" aria-label="Permalink to &quot;Supprimer la route après l&#39;examen&quot;">​</a></h3><p>Sur Kali, supprimer uniquement les routes ajoutées manuellement et présentes dans <code>ip route</code> ; ne pas toucher aux routes VPN préexistantes.</p><p class="oscp-command-note">Sur Kali : exécuter la commande dans un terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> del</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.16.20.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> del</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.16.30.0/24</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ligolo2</span></span></code></pre></div><p>Si les interfaces TUN ont été créées manuellement, vérifier qu&#39;aucune session ne les utilise avant <code>sudo ip link delete ligolo</code> ou <code>sudo ip link delete ligolo2</code>. Les routes créées automatiquement par des versions récentes peuvent être gérées par Ligolo.</p><h2 id="sources-officielles" tabindex="-1">Sources officielles <a class="header-anchor" href="#sources-officielles" aria-label="Permalink to &quot;Sources officielles&quot;">​</a></h2><ul><li><p><a href="https://docs.ligolo.ng/" target="_blank" rel="noreferrer">Ligolo-ng: introduction et limites réseau</a></p></li><li><p><a href="https://docs.ligolo.ng/Quickstart/" target="_blank" rel="noreferrer">Ligolo-ng: Quickstart, interface, certificat et routage</a></p></li><li><p><a href="https://docs.ligolo.ng/sample/double/" target="_blank" rel="noreferrer">Ligolo-ng: double pivot</a></p></li><li><p><a href="https://docs.ligolo.ng/Listeners/" target="_blank" rel="noreferrer">Ligolo-ng: listeners</a></p></li><li><p><a href="https://docs.ligolo.ng/Localhost/" target="_blank" rel="noreferrer">Ligolo-ng: accès au localhost de l&#39;agent</a></p></li><li><p><a href="https://docs.ligolo.ng/Config-File/" target="_blank" rel="noreferrer">Ligolo-ng: configuration v0.8 et routes persistantes</a></p></li><li><p><a href="https://github.com/krovs/oscp-notes/blob/main/docs/17_port_red_tun.md" target="_blank" rel="noreferrer">Notes krovs: tunnels complémentaires</a></p></li></ul>`,165)]))}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
